  builder_.add_RELATIVE_VELOCITY_M_PER_S(RELATIVE_VELOCITY_M_PER_S);
  builder_.add_IMPACTOR_L_C_M(IMPACTOR_L_C_M);
  builder_.add_IMPACTOR_MASS_KG(IMPACTOR_MASS_KG);
  builder_.add_TARGET_L_C_M(TARGET_L_C_M);
  builder_.add_TARGET_MASS_KG(TARGET_MASS_KG);
  builder_.add_COMMENT(COMMENT);
  builder_.add_ASSUMPTIONS(ASSUMPTIONS);
  builder_.add_FRAGMENTS(FRAGMENTS);
  builder_.add_FRAGMENT_COUNT(FRAGMENT_COUNT);
  builder_.add_MODEL_VERSION(MODEL_VERSION);
  builder_.add_MODEL_NAME(MODEL_NAME);
  builder_.add_SEED(SEED);
  builder_.add_IMPACTOR_NORAD_CAT_ID(IMPACTOR_NORAD_CAT_ID);
  builder_.add_IMPACTOR_OBJECT_NAME(IMPACTOR_OBJECT_NAME);
  builder_.add_NORAD_CAT_ID(NORAD_CAT_ID);
  builder_.add_OBJECT_ID(OBJECT_ID);
  builder_.add_OBJECT_NAME(OBJECT_NAME);
  builder_.add_REF_FRAME(REF_FRAME);
  builder_.add_TIME_SYSTEM(TIME_SYSTEM);
  builder_.add_EPOCH(EPOCH);
  builder_.add_ORIGINATOR(ORIGINATOR);
  builder_.add_CREATION_DATE(CREATION_DATE);
  builder_.add_MESSAGE_ID(MESSAGE_ID);
  builder_.add_CATASTROPHIC(CATASTROPHIC);
  builder_.add_OBJECT_CLASS(OBJECT_CLASS);
  builder_.add_EVENT_TYPE(EVENT_TYPE);
  return builder_.Finish();
