inline const SBM *GetSBM(const void *buf) {
  return ::flatbuffers::GetRoot<SBM>(buf);
}

inline const SBM *GetSizePrefixedSBM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SBM>(buf);
}

inline const char *SBMIdentifier() {
  return "$SBM";
}

inline bool SBMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SBMIdentifier());
}

inline bool SizePrefixedSBMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SBMIdentifier(), true);
}

template <bool B = false>
inline bool VerifySBMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SBM>(SBMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSBMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SBM>(SBMIdentifier());
}

inline void FinishSBMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SBM> root) {
  fbb.Finish(root, SBMIdentifier());
}

inline void FinishSizePrefixedSBMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SBM> root) {
  fbb.FinishSizePrefixed(root, SBMIdentifier());
}

inline std::unique_ptr<SBMT> UnPackSBM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SBMT>(GetSBM(buf)->UnPack(res));
}

inline std::unique_ptr<SBMT> UnPackSizePrefixedSBM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SBMT>(GetSizePrefixedSBM(buf)->UnPack(res));
}

